// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";

/// @title KipuBank V1
/// @notice Contrato principal del banco descentralizado
/// @dev Gestiona depósitos y préstamos usando Chainlink y USDC
contract KipuBank is Ownable, ReentrancyGuard {
    IERC20 public USDC;
    AggregatorV3Interface public dataFeed;

    mapping(address => uint256) public balances;
    mapping(address => bool) public isRegistered;

    /// @notice Constructor del contrato
    /// @param _feed Dirección del oráculo de Chainlink
    /// @param _usdc Dirección del token USDC
    constructor(address _feed, address _usdc) Ownable(msg.sender) {
        USDC = IERC20(_usdc);
        dataFeed = AggregatorV3Interface(_feed);
    }

    /// @notice Permite al usuario registrarse en KipuBank
    function register() external {
        require(!isRegistered[msg.sender], "Ya registrado");
        isRegistered[msg.sender] = true;
    }

    /// @notice Permite depositar USDC en el banco
    /// @param amount Monto en USDC a depositar
    function deposit(uint256 amount) external nonReentrant {
        require(isRegistered[msg.sender], "No registrado");
        require(amount > 0, "Monto invalido");

        require(USDC.transferFrom(msg.sender, address(this), amount), "Fallo transferencia");
        balances[msg.sender] += amount;
    }

    /// @notice Permite retirar fondos
    /// @param amount Monto en USDC a retirar
    function withdraw(uint256 amount) external nonReentrant {
        require(balances[msg.sender] >= amount, "Fondos insuficientes");

        balances[msg.sender] -= amount;
        require(USDC.transfer(msg.sender, amount), "Fallo transferencia");
    }

    /// @notice Obtiene el precio actual del oráculo
    /// @return price Precio actual reportado por Chainlink
    function getLatestPrice() external view returns (int256) {
        (, int256 price,,,) = dataFeed.latestRoundData();
        return price;
    }
}

